function filterPanel(ps,inline){const today=C.today(),ctx=searchCtx(),counts=X.facetCounts(ps,filters,today,ctx),n=activeFilterCount(),total=results(ps).length,label=new Intl.Collator(uiLang()).compare,countries=Object.keys(counts.country).map(k=>[k,countryName(k)]).sort((a,b)=>label(a[1],b[1])),cities=Object.keys(counts.city).map(k=>[k,cityName(k)]).sort((a,b)=>label(a[1],b[1])),opts=(xs,current)=>`<option value="">${E(t('common.all'))}</option>`+xs.map(([v,l])=>`<option value="${E(v)}" ${v===current?'selected':''}>${E(l)}</option>`).join(''),state=[['ongoing'],['upcoming'],['ended'],['permanent']].filter(([v])=>filters.state===v||ps.some(p=>X.status(p,today)===v)),kind=['permanent','temporary'].filter(v=>filters.kind===v||ps.some(p=>p.content_type===v)),cond=filters.free||filters.indoor||ps.some(p=>p.free===true||p.indoor===true),detailKeys=['installation_method','technology','envelope_type','operating_status'],more=detailKeys.map(k=>facetGroup(k,counts[k],ps)).join(''),moreOn=detailKeys.some(k=>listOf(filters[k]).length),types=facetChips('project_type',counts.project_type,null,ps);
 return `<div class="sheet-head">${inline?'':`<button type="button" class="icon-button" data-close-filters aria-label="${E(t('filter.close'))}">${I('x')}</button>`}<h2 id="filterTitle">${E(t('filter.title'))}${n?`<span class="count-badge">${n}</span>`:''}</h2><button type="button" class="text-link sheet-clear" data-reset-all ${n?'':'disabled'}>${E(t('filter.clearAll'))}</button></div><div class="sheet-body">${types?`<div class="filter-group"><h3>${E(t('facet.project_type'))}</h3>${types}</div>`:''}<div class="filter-group"><h3>${E(t('filter.place'))}</h3>${facetGroup('region',counts.region,ps)}<div class="field-grid"><label>${E(t('filter.country'))}<select data-search-filter="country">${opts(countries,filters.country)}</select></label><label>${E(t('filter.city'))}<select data-search-filter="city" ${cities.length?'':'disabled'}>${opts(cities,filters.city)}</select></label></div></div><div class="filter-group"><h3 id="yearRangeLabel">${E(t('filter.years'))}</h3><div class="field-grid year-range" role="group" aria-labelledby="yearRangeLabel"><label>${E(t('filter.yearFrom'))}<input type="number" inputmode="numeric" min="1800" max="2100" step="1" placeholder="1990" data-search-filter="year_from" value="${E(filters.year_from||'')}"></label><label>${E(t('filter.yearTo'))}<input type="number" inputmode="numeric" min="1800" max="2100" step="1" placeholder="${new Date().getFullYear()}" data-search-filter="year_to" value="${E(filters.year_to||'')}"></label></div><p class="filter-note">${E(t('filter.yearNote'))}</p></div><div class="filter-group"><h3>${E(t('filter.images'))}</h3><div class="chips" role="group" aria-label="${E(t('filter.images'))}"><button type="button" class="chip${filters.has_photo?' active':''}" data-filter-toggle="has_photo" aria-pressed="${!!filters.has_photo}">${I('images')}${E(t('filter.hasPhoto'))}</button></div></div>${more?`<div class="filter-group filter-more"><h3><button type="button" class="more-toggle" data-more-filters aria-expanded="${moreOn||moreFilters}" aria-controls="moreFilters">${E(t('filter.more'))}${I('caret-down','more-caret')}</button></h3><div id="moreFilters"${moreOn||moreFilters?'':' hidden'}>${more}</div></div>`:''}${state.length||kind.length?`<div class="filter-group"><h3>${E(t('filter.schedule'))}</h3><div class="field-grid">${state.length?`<label>${E(t('filter.state'))}<select data-search-filter="state"><option value="">${E(t('common.all'))}</option>${state.map(([v])=>`<option value="${v}" ${filters.state===v?'selected':''}>${E(t('state.'+v))}</option>`).join('')}</select></label>`:''}${kind.length?`<label>${E(t('filter.kind'))}<select data-search-filter="kind"><option value="">${E(t('common.all'))}</option>${kind.map(v=>`<option value="${v}" ${filters.kind===v?'selected':''}>${E(t('kind.'+v))}</option>`).join('')}</select></label>`:''}</div></div>`:''}${cond?`<div class="filter-group"><h3>${E(t('filter.conditions'))}</h3><div class="chips" role="group" aria-label="${E(t('filter.conditions'))}"><button type="button" class="chip ${filters.free?'active':''}" data-filter-toggle="free" aria-pressed="${!!filters.free}">${E(t('filter.free'))}</button><button type="button" class="chip ${filters.indoor?'active':''}" data-filter-toggle="indoor" aria-pressed="${!!filters.indoor}">${E(t('filter.indoor'))}</button></div></div>`:''}</div>${inline?'':`<div class="sheet-foot"><button type="button" class="button" data-close-filters>${E(t('filter.show',{n:fmt(total)}))}</button></div>`}`}
function filterSheet(ps,inline=false){const n=activeFilterCount(),open=inline||advancedOpen;return `<details class="advanced-filters${inline?' inline':''}${!inline&&open&&sheetSettled?' settled':''}" ${open?'open':''}><summary class="filter-button" aria-label="${E(n?t('filter.ariaActive',{n}):t('filter.aria'))}">${I('sliders-horizontal')}<span class="filter-label">${E(t('filter.title'))}</span>${n?`<span class="count-badge" aria-hidden="true">${n}</span>`:''}</summary><div class="filter-sheet">${inline?'':`<button type="button" class="filter-backdrop" data-close-filters tabindex="-1" aria-label="${E(t('filter.close'))}"></button>`}<div class="filter-panel" id="filterPanel" role="group" aria-labelledby="filterTitle">${filterPanel(ps,inline)}</div></div></details>`}
function activeChips(){const items=[],y=[filters.year_from,filters.year_to].map(v=>String(v||'').trim());if(scope!=='all')items.push(['scope',scopeLabel()]);if(filters.category&&filters.category!=='전체')items.push(['category',category({primary_category:filters.category})]);if(filters.country)items.push(['country',countryName(filters.country)]);if(filters.city)items.push(['city',cityName(filters.city)]);for(const [k,v] of X.activeFacets(filters))items.push([`facet:${k}:${v}`,facetLabel(k,v)]);if(y[0]||y[1])items.push(['years',y[0]&&y[1]?t('filter.yearsChip',{from:y[0],to:y[1]}):y[0]?t('filter.yearFromChip',{from:y[0]}):t('filter.yearToChip',{to:y[1]})]);if(filters.state)items.push(['state',t('stateChip.'+filters.state)]);if(filters.kind)items.push(['kind',t('kind.'+filters.kind)]);if(filters.year)items.push(['year',filters.year]);if(filters.has_photo)items.push(['has_photo',t('filter.hasPhoto')]);if(filters.free)items.push(['free',t('filter.free')]);if(filters.indoor)items.push(['indoor',t('filter.indoor')]);return items.length?`<div class="active-filters" role="group" aria-label="${E(t('filter.active'))}">${items.map(([k,l])=>`<button type="button" class="chip removable" data-clear-filter="${E(k)}" aria-label="${E(t('chip.remove',{label:l}))}">${E(l)}${I('x','icon-sm')}</button>`).join('')}${items.length>1?`<button type="button" class="text-link" data-reset-all>${E(t('filter.clearAll'))}</button>`:''}</div>`:''}
