// ===== Home (v0.17): a digital museum of media architecture =====
// With the static dataset everything comes from home.json (client/dataset.js reads nothing else for this page); without
// it, the same sections are computed from the places this browser has (curated seed, Wikidata sync). The same image
// rules apply either way: only photos with media-active evidence, else the designed placeholder or the LED graphic.
const HOME_TYPES=['media_facade','projection_mapping','light_art','media_architecture','festival_program','interactive_installation','urban_screen','media_wall'];
// Themes cut across the project types; home.json may bring editorial ones instead.
const THEMES=[['screens',['media_facade','urban_screen','media_wall']],['surfaces',['projection_mapping']],['festivals',['festival_program']],['responsive',['interactive_installation','media_architecture']],['medium',['light_art']]];
function homeData(){const ds=window.AOL_DATASET;if(ds?.status==='ok'&&ds.home)return {...ds.home,source:'dataset'};if(ds?.status==='probing')return {source:'probing',hero:[],featured:[],regions:[],types:[],themes:[],recent:[],counts:{}};
 const ps=allPlaces().filter(p=>p.origin!=='wikidata'),lit=p=>!!photoFor(p,'home'),count=f=>{const c=new Map();for(const p of ps){const k=f(p);if(k)c.set(k,(c.get(k)||0)+1)}return c},rep=f=>ps.find(p=>f(p)&&lit(p))||null,regions=[...count(p=>X.regionKey(p))].sort((a,b)=>b[1]-a[1]).map(([key,n])=>({key,count:n,place:rep(p=>X.regionKey(p)===key)})),types=[...count(p=>X.typeOf(p))].sort((a,b)=>b[1]-a[1]).map(([key,n])=>({key,count:n,place:rep(p=>X.typeOf(p)===key)})),stamp=p=>String(p.first_collected_at||p.created_at||''),recent=ps.filter(stamp).sort((a,b)=>stamp(b).localeCompare(stamp(a))).slice(0,8),featured=[...ps.filter(lit),...ps.filter(p=>!lit(p)&&(p.MVP_priority==='A'||p.mvp_priority==='A'))].slice(0,7);
 return {source:'local',hero:[],featured,regions,types,themes:[],recent,counts:{projects:ps.length,countries:new Set(ps.map(p=>X.region(p).iso).filter(Boolean)).size}}}
