function mapPage(){const ps=scoped();return `<div class="map-explorer${sheetFull?' sheet-full':''}" id="mapExplorer"${sheetH?` style="--sheet-height:${sheetH}px"`:''}><div class="map-head"><h1 class="map-title">${E(t('map.title'))}</h1><div class="search-row"><div class="search-box">${I('magnifying-glass')}<input class="search-field" id="placeSearch" type="search" aria-label="${E(t('map.search'))}" value="${E(filters.q)}" placeholder="${E(t('map.search'))}" autocomplete="off"></div><div class="filter-slot" id="filterSlot">${filterSheet(ps)}</div></div>${typeChips(ps)}</div><div class="map-stage"><div id="mapCanvas" class="map-placeholder"><div class="map-consent"><span class="map-consent-mark">${I('map-trifold')}</span><h2>${E(t('map.consentTitle'))}</h2><p>${E(t('map.consentBody'))}</p><div class="map-consent-actions"><button class="button" data-load-map>${I('map-trifold')}${E(t('map.load'))}</button><button type="button" class="button subtle" data-nearby>${I('crosshair')}${E(t('map.nearby'))}</button></div></div></div><div class="map-fabs"><button type="button" class="glass-button round" data-nearby aria-label="${E(t('map.nearbyAria'))}">${I('crosshair')}</button></div></div><div class="map-list"><button class="map-handle" id="mapHandle" type="button" aria-label="${E(t('map.sheetHandle'))}"></button><div class="map-list-head">${modeSwitch('map')}</div><div id="mapMessage" role="status"></div><div id="mapResults" tabindex="0" role="region" aria-label="${E(t('map.listAria'))}">${mapResultHTML()}</div></div></div>`}
// One map at a time: its markers live in one feature group, and every single-place dot is drawn by one shared canvas
// renderer (a renderer per rebuild would stack full-size canvases that all redraw on every move). var: render() runs
// before this line on first load.
let mapLibraryPromise=null;var mapLoading=false,exploreTimer=null,currentMap=null,mapMarkers=[],mapLayer=null,mapRenderer=null,mapShown=[],mapTimer=null;const MAP_TYPING_DELAY=200;
// Leaflet (self-hosted, assets/vendor/leaflet) loads once, when a map is first asked for; the tiles come from
// OpenStreetMap (config TILE_URL) with its attribution.
function loadLeaflet(){if(window.L)return Promise.resolve();if(!mapLibraryPromise)mapLibraryPromise=new Promise((resolve,reject)=>{const css=document.createElement('link');css.rel='stylesheet';css.href='./assets/vendor/leaflet/leaflet.css';document.head.appendChild(css);const script=document.createElement('script');script.src='./assets/vendor/leaflet/leaflet.js';const timer=setTimeout(()=>reject(Error('timeout')),12000);script.onload=()=>{clearTimeout(timer);resolve()};script.onerror=()=>{clearTimeout(timer);reject(Error('network'))};document.head.appendChild(script)}).catch(e=>{mapLibraryPromise=null;throw e});return mapLibraryPromise}
function tiles(){return L.tileLayer(window.AOL_CONFIG?.TILE_URL||'https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap contributors</a>'})}
// The place page's map: loaded only when asked, one marker, no scroll-wheel zoom (the page scrolls under it).
var miniMapInst=null;async function loadMiniMap(){const box=$('#miniMap');if(!box||box.classList.contains('map-loaded'))return;const btn=box.querySelector('[data-mini-map]');if(btn)btn.disabled=true;try{await loadLeaflet();if(!box.isConnected)return;const ll=[Number(box.dataset.lat),Number(box.dataset.lng)];box.innerHTML='';box.classList.add('map-loaded');miniMapInst=L.map(box,{scrollWheelZoom:false}).setView(ll,15);tiles().addTo(miniMapInst);L.circleMarker(ll,{radius:9,weight:3,color:'#FFFFFF',fillColor:'#6B52DE',fillOpacity:1}).addTo(miniMapInst)}catch{if(btn)btn.disabled=false;toast(t('map.failed'))}}
async function loadMap(){const box=$('#mapCanvas'),message=$('#mapMessage');if(!box)return;message.textContent=t('map.loading');mapLoading=true;try{await loadLeaflet();if(!box.isConnected)return;box.innerHTML='';box.className='map-loaded';currentMap=L.map(box,{zoomControl:false,worldCopyJump:true,minZoom:1}).setView([25,10],2);L.control.zoom({position:'topright',zoomInTitle:t('map.zoomIn'),zoomOutTitle:t('map.zoomOut')}).addTo(currentMap);mapRenderer=L.canvas({padding:.5});mapLayer=L.featureGroup().addTo(currentMap);mapShown=[];tiles().addTo(currentMap);mapFitted=false;mapProj=null;mapShown=mapProjects();fitMap();currentMap.on('moveend',()=>{drawMap();const target=$('#mapResults');if(target)target.innerHTML=mapResultHTML(currentMap.getBounds())});drawMap();updateMapList(mapShown);message.textContent=t('map.loaded')}catch{mapLibraryPromise=null;message.textContent=t('map.failed')}}

// Account-isolated storage: never upload the guest workspace without consent.
let activeUser=null;
const rawStorage=storage;
const scopedStorage={getItem(k){return rawStorage.getItem(k===C.KEY&&activeUser?'aol12_user_'+activeUser:k)},setItem(k,v){return rawStorage.setItem(k===C.KEY&&activeUser?'aol12_user_'+activeUser:k,v)}};
