function articlePage(id){const a=articles().find(x=>x.id===id);return a?`<article class="article"><header class="article-head"><p class="eyebrow">빛의 건축 읽기</p><h1>${E(a.title)}</h1>${a.summary?`<p class="article-dek">${E(a.summary)}</p>`:''}<p class="article-byline"><span class="byline-mark" aria-hidden="true">${I('arch')}</span><span>${E(a.author||'빛의 건축')}${a.published_at?' · '+E(a.published_at.slice(0,10)):''} · ${readMinutes(a)}분 읽기</span></p></header><div class="record-note article-body">${E(a.body)}</div>${a.source_url?`<p class="article-source">${link(a.source_url,'원문·출처 보기')}</p>`:''}<div class="article-foot"><a class="button tonal" href="#magazine">${I('book-open-text')}다른 글 보기</a><a class="button subtle" href="#routes">${I('path')}에디터 코스</a></div></article>`:notFound()}

// ===== Place page (v0.17): visual first, one layout for every record =====
// The gallery (media-active photos first, then videos, then photos of the architecture labelled as context), then
// name, place, type, people, description, visit facts when a source states them, official and source links, the
// location on a map (loaded on request), similar projects, and the visitor's own notes. No review or pipeline states.
function videosOf(p){const v=window.AOLDataset?.videos;return v?[...(v(p.place_id)||[]),...(p.archive_place_id?v(p.archive_place_id)||[]:[])]:[]}
