// Coordinates on the page: the place's own (any source that passes the map rule) or the live photo sync's Wikidata ones.
function coordsOf(p){if(X.mappable(p)||C.coords(p)&&!isArchive(p)&&!isSynced(p))return C.coords(p);const i=window.AOL_LIVE?.info?.[p.place_id];return i?.coord&&Number.isFinite(i.coord.lat)&&Number.isFinite(i.coord.lon)?[i.coord.lat,i.coord.lon]:null}
function mapLinkFor(p){const c=coordsOf(p);return c?`https://www.openstreetmap.org/?mlat=${c[0]}&mlon=${c[1]}#map=16/${c[0]}/${c[1]}`:''}
function detailHero(p,list=photos(p)){const m=list[0],saved=db.saved.includes(p.place_id),id=E(p.place_id),name=nm(p);return `<div class="detail-hero${m?'':' no-photo'}">${m?`<div class="card-art detail-art">${imgTag(m,name,{eager:true,sizes:'(min-width:1024px) 72vw, 100vw'})}${creditButton(p,m)}</div>${tierOf(m)===4?`<span class="context-tag">${E(t('photo.contextTag'))}</span>`:''}`:`<div class="card-art detail-art">${placeholder(p,'ph-hero')}</div>`}<div class="hero-controls"><button type="button" class="glass-button round hero-back" data-app-back aria-label="${E(t('shell.back'))}">${I('arrow-left')}</button><span class="hero-spacer"></span><button type="button" class="glass-button round" data-share="${id}" aria-label="${E(t('detail.share'))}">${I('share-network')}</button><button type="button" class="glass-button round${saved?' saved':''}" data-save="${id}" aria-label="${E(t(saved?'card.unsave':'card.save',{name}))}" aria-pressed="${saved}">${I(saved?'heart-fill':'heart')}</button></div>${list.length>1?`<button type="button" class="photo-count" data-scroll-to="detailPhotos">${I('images')}${E(t('detail.photoCount',{n:list.length}))}</button>`:''}</div>`}
function quickActions(p){const id=E(p.place_id),saved=db.saved.includes(p.place_id),c=coordsOf(p);return `<div class="quick-actions"><button type="button" class="quick${saved?' saved':''}" data-save="${id}">${I(saved?'heart-fill':'heart')}<span>${E(t(saved?'detail.saved':'detail.save'))}</span></button><button type="button" class="quick" data-add-route="${id}" aria-label="${E(t('detail.addCourseShort'))}">${I('path')}<span>${E(t('card.course'))}</span></button>${c||p.address?`<button type="button" class="quick" data-scroll-to="detailMap">${I('map-pin')}<span>${E(t('detail.location'))}</span></button>`:`<span class="quick disabled">${I('map-pin')}<span>${E(t('detail.noMap'))}</span></span>`}<button type="button" class="quick" data-share="${id}">${I('share-network')}<span>${E(t('detail.shareShort'))}</span></button></div>`}
function actionBar(p){const c=coordsOf(p);return `<div class="detail-actionbar"><button type="button" class="button tonal large" data-add-route="${E(p.place_id)}">${I('path')}${E(t('detail.addCourseShort'))}</button>${c||p.address?`<button type="button" class="button large" data-scroll-to="detailMap">${I('map-pin')}${E(t('detail.seeLocation'))}</button>`:''}</div>`}
function figureHTML(p,m){const tier=tierOf(m),cap=m.caption_i18n?.[uiLang()]||m.caption||'';return `<figure class="gallery-figure${tier===4?' context':''}" data-tier="${tier}"><a class="gallery-photo" href="${E(C.safeURL(m.full_url)||mediaURL(m))}" target="_blank" rel="noopener noreferrer">${imgTag(m,nm(p)+(tier===4?' · '+t('photo.contextTag'):''),{cls:'photo',sizes:'(min-width:1024px) 36vw, (min-width:600px) 50vw, 100vw'})}</a><figcaption>${tier===4?`<span class="role-tag">${E(t('photo.contextTag'))}</span>`:''}<b class="credit-line">© ${E(m.creator||t('photo.authorCheck'))} · ${E(m.license_code||'')}</b>${cap||m.captured_at?`<span>${[m.captured_at?E(t('photo.taken',{v:m.captured_at})):'',E(cap)].filter(Boolean).join(' · ')}</span>`:''}<span class="figure-links">${link(m.source_url,t('photo.original'))}${link(m.license_url,t('photo.terms'))}</span></figcaption></figure>`}
function videoHTML(p,v){return `<figure class="gallery-figure video-figure" data-tier="${tierOf(v)}"><div class="gallery-video"><video controls muted playsinline preload="none"${v.poster?` poster="${E(v.poster)}"`:''} aria-label="${E(t('photo.video',{name:nm(p)}))}"><source src="${E(v.src)}"${v.type?` type="${E(v.type)}"`:''}></video></div><figcaption><b class="credit-line">© ${E(v.author||v.attribution||t('photo.authorCheck'))} · ${E(v.license)}</b><span class="figure-links">${link(v.page||v.src,t('photo.original'))}${link(v.license_url,t('photo.terms'))}</span></figcaption></figure>`}
function gallerySection(p,list,vids,loading){const media=list.filter(m=>tierOf(m)<=3),context=list.filter(m=>tierOf(m)===4),any=list.length||vids.length;return `<section class="detail-section gallery-section" id="detailPhotos"><h2>${E(t('photos.title'))}</h2>${any?`<div class="image-gallery">${media.map(m=>figureHTML(p,m)).join('')}${vids.map(v=>videoHTML(p,v)).join('')}${context.map(m=>figureHTML(p,m)).join('')}</div>`:loading?`<div class="image-gallery" aria-busy="true">${'<span class="sk sk-photo" aria-hidden="true"></span>'.repeat(2)}</div>`:`<div class="gallery-empty">${placeholder(p)}<p>${E(t('photos.none'))}</p></div>`}${context.length?`<p class="section-note">${E(t('photos.contextNote'))}</p>`:''}<p class="section-note">${E(t('photos.reportLead'))} <a href="./support.html">${E(t('photos.report'))}</a></p></section>`}
// Facts in plain words: only values a record has (no field states, no list of unknowns).
function factsSection(p){const groups=Object.entries(T.fields).map(([g,keys])=>[g,keys.filter(k=>!['name_original','name_en','name_ko','operating_status'].includes(k)).map(k=>[k,fieldValue(p,k)]).filter(r=>r[1])]).filter(([,rows])=>rows.length),extra=!isArchive(p)&&!isSynced(p)&&p.project_year?`<div class="kv"><dt>${E(t('field.project_year'))}</dt><dd>${E(p.project_year)}</dd></div>`:'';if(!groups.length&&!extra)return '';return `<section class="detail-section facts" id="detailArchive"><h2>${E(t('facts.title'))}</h2>${groups.map(([g,rows])=>`<div class="field-group"><h3>${E(T.groupLabels[g][uiLang()==='en'?1:0])}</h3><dl class="kv-list">${rows.map(([k,v])=>`<div class="kv"><dt>${E(T.fieldLabel(k,uiLang()))}</dt><dd><bdi>${E(v)}</bdi></dd></div>`).join('')}${g==='basic'?extra:''}</dl></div>`).join('')||`<dl class="kv-list">${extra}</dl>`}</section>`}
// What matters for a visit, only when a source states it: address, hours, fee, the programme and its dates, and the
// dataset's visit facts (operating, seasonal, a period, a note).
function visitSection(p){const L=uiLang(),en=L==='en',v=p.visit,rows=[],ko=s=>en&&/[가-힣]/.test(s)?` lang="ko"`:'',st=v?.status||p.operating_status,hours=p.current_hours_verified||p.typical_hours;
 if(p.address)rows.push([t('field.address'),p.address]);if(hours)rows.push([t('detail.hours'),hours+(p.recommended_time?' · '+t('detail.bestTime',{v:p.recommended_time}):'')]);if(p.free===true||p.free===false)rows.push([t('detail.fee'),t(p.free?'detail.feeFree':'detail.feePaid')]);if(p.current_program)rows.push([t('detail.programme'),p.current_program+(p.program_start||p.program_end?` (${[p.program_start,p.program_end].filter(Boolean).join(' – ')})`:'')]);
 if(st&&st!=='unknown')rows.push([t('facet.operating_status'),vlabel('operating_status',st)]);if(v?.period)rows.push([t('visit.period'),v.period[L]]);if(v?.note)rows.push([t('visit.note'),v.note[L]]);
 if(!rows.length)return '';return `<section class="detail-section visit-info" id="detailVisit"><h2>${E(t('visit.title'))}</h2><dl class="kv-list">${rows.map(([k,x])=>`<div class="kv"><dt>${E(k)}</dt><dd${ko(x)}>${E(x)}</dd></div>`).join('')}</dl><p class="section-note">${E(t('detail.visitWarning'))}</p>${v?.source?link(v.source,t('visit.source')):''}</section>`}
// Official site first, then every source with its publisher; a link known to be broken is named but not linked.
function kindLabel(k){return !k?'':k==='official'?t('sources.official'):k==='encyclopedia'?t('sources.encyclopedia'):k==='commons'?'Wikimedia Commons':T.valid('source_kind',k)?vlabel('source_kind',k):''}
function linksSection(p){const seen=new Set(),items=[],add=(url,title,publisher,kind,broken)=>{const u=C.safeURL(url);if(!u||seen.has(u))return;seen.add(u);items.push({u,title,publisher,kind,broken})},web=p.official_url||p.website,i=window.AOL_LIVE?.info?.[p.place_id];if(web)add(web,null,null,'official',p.update_status==='link_broken');for(const s of sourcesOf(p))add(s.url,s.title,s.publisher,s.kind,s.link_state==='broken');if(i?.website)add(i.website,null,null,'official');if(/^Q\d+$/.test(i?.qid||''))add('https://www.wikidata.org/wiki/'+i.qid,'Wikidata '+i.qid,'Wikidata','wikidata');if(i?.commonsCategory)add('https://commons.wikimedia.org/wiki/Category:'+encodeURIComponent(String(i.commonsCategory).replace(/ /g,'_')),t('live.commons'),'Wikimedia Commons',null);
 const host=u=>{try{return new URL(u).host.replace(/^www\./,'')}catch{return ''}};return `<section class="detail-section" id="detailSources"><h2>${E(t('sources.title'))}</h2>${items.length?`<ul class="source-list">${items.map(x=>`<li class="source-item${x.broken?' broken':''}"><div class="source-head"><b>${E(x.publisher||x.title||host(x.u))}</b>${kindLabel(x.kind)?`<span class="pill">${E(kindLabel(x.kind))}</span>`:''}</div>${x.title&&x.title!==x.publisher?`<p class="source-title">${E(x.title)}</p>`:''}${x.broken?`<p class="link-broken">${I('link-break','icon-sm')}${E(t('sources.broken'))} · ${E(host(x.u))}</p>`:link(x.u,host(x.u)||t('sources.open'))}</li>`).join('')}</ul>`:`<p class="section-empty">${E(t('sources.none'))}</p>`}</section>`}
// The location: a map loaded only when asked (the tiles come from OpenStreetMap), or an honest address search.
function mapSection(p){const c=coordsOf(p),osm=mapLinkFor(p);if(!c)return p.address?`<section class="detail-section" id="detailMap"><h2>${E(t('detail.location'))}</h2><p class="map-address"${uiLang()==='en'?' lang="ko"':''}>${E(p.address)}</p><div class="actions">${link('https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(p.address),t('detail.searchAddress'),'button subtle source-link')}</div></section>`:'';return `<section class="detail-section" id="detailMap"><h2>${E(t('detail.location'))}</h2><div class="mini-map" id="miniMap" data-lat="${c[0]}" data-lng="${c[1]}"><div class="mini-map-preview"><span class="mini-pin" aria-hidden="true">${I('map-pin')}</span><button type="button" class="button" data-mini-map>${I('map-trifold')}${E(t('map.load'))}</button><p class="mini-note">${E(t('detail.mapNote'))}</p></div></div><p class="map-coords"><span class="tnum">${E(c[0].toFixed(5)+', '+c[1].toFixed(5))}</span>${placeLine(p)?' · '+E(placeLine(p)):''}</p><div class="actions">${link(osm,t('project.osm'),'text-link')}</div></section>`}
function glance(p){const year=X.yearOf(p),people=creditsOf(p).slice(0,3).map(c=>(uiLang()==='en'&&c.name_en||c.name)).join(', '),web=C.safeURL(p.official_url||p.website||window.AOL_LIVE?.info?.[p.place_id]?.website),rows=[[t('facet.project_type'),vlabel('project_type',X.typeOf(p))||category(p)],[t('project.where'),placeLine(p)],[t('filter.years'),year?String(year):''],[t('facts.people'),people]].filter(r=>r[1]);return `<div class="info-card glance"><h2>${E(t('facts.glance'))}</h2><dl class="kv-list">${rows.map(([k,v])=>`<div class="kv"><dt>${E(k)}</dt><dd><bdi>${E(v)}</bdi></dd></div>`).join('')}</dl><div class="info-actions"><button class="button large" data-add-route="${E(p.place_id)}">${I('plus')}${E(t('detail.addCourse'))}</button>${web?link(web,t('project.website'),'button subtle large source-link'):''}</div></div>`}
function detail(p){if(!p)return notFound();const list=photos(p),vids=videosOf(p),loading=detailLoading(p),name=nm(p),en=uiLang()==='en',year=X.yearOf(p),orig=p.name_original&&p.name_original!==name,other=en?(p.name_kr&&p.name_kr!==name?p.name_kr:''):(p.name_en&&p.name_en!==name?p.name_en:''),summary=en?p.summary_en||p.summary_ko:p.summary_ko||p.summary_en,lead=(!isArchive(p)&&!isSynced(p)?p.short_description:'')||summary||p.short_description,essay=!isArchive(p)&&!isSynced(p)?p.expert_description||p.description:'',curatedText=!isArchive(p)&&!isSynced(p)&&en,visit=visitSection(p),facts=factsSection(p),map=mapSection(p),sim=similarSection(p),tabs=[['detailPhotos','tab.photos'],...(essay||p.why_it_matters?[['detailAbout','tab.about']]:[]),...(visit?[['detailVisit','tab.visit']]:[]),...(facts?[['detailArchive','tab.facts']]:[]),['detailSources','tab.sources'],...(map?[['detailMap','tab.map']]:[]),...(sim?[['detailRelated','tab.related']]:[])];
 return `<article class="detail" data-place="${E(p.place_id)}">${detailHero(p,list)}<div class="detail-sheet"><div class="detail-body"><header class="detail-title"><p class="eyebrow">${E([category(p),placeLine(p)].filter(Boolean).join(' · '))}</p><h1><bdi>${E(name)}</bdi></h1>${orig?`<p class="detail-sub"><bdi lang="${E(p.name_original_lang||'')}">${E(p.name_original)}</bdi></p>`:other?`<p class="detail-sub"><bdi${en?' lang="ko"':''}>${E(other)}</bdi></p>`:''}<div class="detail-pills">${visitPill(p)}${year?`<span class="pill">${year}</span>`:''}${p.free===true?`<span class="pill">${E(t('filter.free'))}</span>`:''}${p.indoor===true?`<span class="pill">${E(t('filter.indoor'))}</span>`:p.indoor===false?`<span class="pill">${E(t('detail.outdoor'))}</span>`:''}</div></header>${quickActions(p)}<nav class="section-tabs" aria-label="${E(t('tab.label'))}">${tabs.map(([id,k],i)=>`<button type="button" class="${i===0?'active':''}" data-scroll-to="${id}">${E(t(k))}</button>`).join('')}</nav>${lead?`<div class="detail-lead"${curatedText||en&&/[가-힣]/.test(lead)?' lang="ko"':''}><p class="detail-description">${E(lead)}</p></div>`:''}<div class="detail-grid"><div class="detail-main">${gallerySection(p,list,vids,loading)}${essay||p.why_it_matters?`<section class="detail-section" id="detailAbout"><h2>${E(t('detail.essay'))}</h2>${essay?`<p class="reading"${en?' lang="ko"':''}>${E(essay)}</p>`:''}${p.why_it_matters?`<p class="quote"${en?' lang="ko"':''}>${E(p.why_it_matters)}</p>`:''}</section>`:''}${visit}${facts}${linksSection(p)}${map}${assessmentsSection(p)}${citationSection(p)}${visitsSection(p)}</div><aside class="detail-aside" id="detailInfo">${glance(p)}</aside></div></div>${sim}</div>${actionBar(p)}</article>`}

// ===== Facts of a place page (docs/ARCHIVE_SPEC.md §6): the same for curated places, Wikidata items and archive
// projects; only values a record has are shown.
function creditsOf(p){const own=Array.isArray(p.credits)?p.credits:[];return own.length?own:LEGACY_CREDITS.filter(([k])=>p[k]).map(([k,role])=>({role,name:p[k]}))}
function roleLabel(r){return r==='creator'?t('role.creator'):vlabel('credit_role',r)}
function listLabels(name,v){return Array.isArray(v)?v.map(x=>vlabel(name,x)).join(', '):typeof v==='string'?v:''}
// A field's display value; '' = not known.
function fieldValue(p,k){const L=uiLang(),num=(v,u)=>typeof v==='number'&&Number.isFinite(v)?v.toLocaleString(L==='en'?'en-US':'ko-KR')+u:'';switch(k){
 case 'name_original':return p.name_original||'';case 'name_en':return p.name_en||'';case 'name_ko':return p.name_ko||(!isSynced(p)&&!isArchive(p)?p.name_kr:'')||'';
 case 'country_iso2':{const r=X.region(p);return r.iso?countryName(r.iso):r.country||''}
 case 'city':return cityName(X.region(p).cityKey);case 'address':return p.address||'';
 case 'project_type':return vlabel('project_type',X.typeOf(p));case 'operating_status':case 'installation_method':case 'envelope_type':return vlabel(k,p[k]);
 case 'technology':return listLabels('technology',p.technologies||p.technology);case 'content_type':return listLabels('content_type',p.content_types);case 'spatial_context':return listLabels('spatial_context',p.spatial_context);
 case 'credits':return creditsOf(p).map(c=>roleLabel(c.role)+': '+(L==='en'&&c.name_en||c.name)).join(' · ');
 case 'display_area_m2':return num(p.display_area_m2,' ㎡');case 'pixel_pitch_mm':return num(p.pixel_pitch_mm,' mm');
 case 'interactive':return p.interactive===true?t('common.yes'):p.interactive===false?t('common.no'):'';
 default:{const v=p[k];return v===null||v===undefined?'':String(v)}}}
// Sources of a record: the archive's own list, Wikidata for synced places, the curated sources and verification links.
function tier(r){return typeof r!=='number'?null:r>=80?'high':r>=55?'medium':'low'}
function shortDate(v){return v?String(v).slice(0,10):''}
function sourcesOf(p){if(isArchive(p)||p.archive_place_id&&Array.isArray(p.sources)&&p.sources.length)return p.sources||[];if(isSynced(p)){const q=p.wikidata||p.place_id.slice(3);return [{title:'Wikidata '+q,url:'https://www.wikidata.org/wiki/'+q,publisher:'Wikidata',kind:'wikidata',license:'CC0 1.0',retrieved_at:window.AOL_GLOBAL?.fetchedAt||null,last_checked_at:null,link_state:'unknown',reliability:70,supports:Object.keys(p.field_status||{}).concat(['name_original','latitude','longitude'])}]}const seen=new Set();return [...D.sources.filter(s=>s.place_id===p.place_id).map(s=>({title:s.title,url:s.url,publisher:s.publisher,kind:null,license:null,retrieved_at:null,last_checked_at:s.checked_date||null,link_state:'unknown',reliability:null,supports:[]})),...[[p.verification_source_1,'official'],[p.verification_source_2,null],[p.source_url,null]].filter(([u])=>u).map(([u])=>({title:null,url:u,publisher:p.source_publisher||null,kind:null,license:null,retrieved_at:null,last_checked_at:p.verified_at||null,link_state:'unknown',reliability:null,supports:[]}))].filter(s=>{const u=C.safeURL(s.url);if(!u||seen.has(u))return false;seen.add(u);return true})}
// Researcher assessments: interpretation, kept apart from the collected data and labelled as such.
function assessmentsSection(p){const list=Array.isArray(p.assessments)?p.assessments:[];if(!list.length)return '';return `<section class="detail-section assessments" id="detailAssess"><h2>${E(t('assess.title'))}</h2><p class="assess-label">${I('seal-question','icon-sm')}${E(t('assess.label'))}</p><ul class="assess-list">${list.map(a=>`<li class="assess-item"><div class="assess-head"><b>${E(String(a.attribute).replace(/_/g,' '))}</b>${a.confidence?`<span class="pill info">${E(t('assess.confidence.'+a.confidence))}</span>`:''}</div><p class="assess-value">${E(a.value)}</p>${a.method?`<p class="assess-meta">${E(t('assess.method'))}: ${E(a.method)}</p>`:''}${a.note?`<p class="assess-note">${E(a.note)}</p>`:''}${a.created_at?`<p class="assess-meta">${E(shortDate(a.created_at))}</p>`:''}</li>`).join('')}</ul></section>`}
// Citation: name, the stable record URL and today's access date.
function recordURL(p){let base=window.AOL_CONFIG?.PUBLIC_URL;if(!base)try{base=new URL('.',location.href).href}catch{base=''}return String(base).replace(/\/+$/,'')+'/#place/'+encodeURIComponent(p.place_id)}
function citation(p){return t('cite.text',{name:nm(p),url:recordURL(p),date:C.today()})}
function citationSection(p){return `<section class="detail-section" id="detailCite"><h2>${E(t('cite.title'))}</h2><blockquote class="citation" id="citationText">${E(citation(p))}</blockquote><div class="cite-actions"><button type="button" class="button tonal" data-copy-citation="${E(p.place_id)}">${I('copy')}${E(t('cite.copy'))}</button></div><p class="section-note">${E(t('cite.note'))}</p></section>`}
// Similar projects with the reasons they are similar.
function reasonText([k,v]){return k==='technology'?t('why.technology',{v:v.map(x=>vlabel('technology',x)).join(', ')}):k==='decade'?t('why.decade',{v}):k==='category'?t('why.category',{v:category({primary_category:v})}):t('why.'+k,{v:vlabel(k==='type'?'project_type':k==='method'?'installation_method':k==='envelope'?'envelope_type':'region',v)})}
function similarSection(p){const list=X.similar(p,allPlaces());if(!list.length)return '';return `<section class="home-section similar" id="detailRelated"><div class="section-head"><div><h2>${E(t('similar.title'))}</h2><small>${E(t('similar.sub'))}</small></div></div><div class="similar-list">${list.map(({place:x,reasons})=>`<a class="similar-item" href="#place/${E(x.place_id)}"><span class="row-art brand-art" aria-hidden="true">${I(catIcon(x))}</span><span class="similar-text"><b>${E(nm(x))}</b><small>${E([category(x),regionText(x)].filter(Boolean).join(' · '))}</small><span class="similar-why">${reasons.map(r=>`<span>${E(reasonText(r))}</span>`).join('')}</span></span>${I('caret-right','row-chev')}</a>`).join('')}</div></section>`}
// ===== Research data page (#data): statistics of the current filtered set, its export and the methodology. =====
// One series per chart: bars in one accent (--chart-bar), the value at each bar's tip, unknowns counted apart.
function barChart(id,title,rows,label,{note='',total=0,unknown=0,limit=0}={}){const max=Math.max(1,...rows.map(r=>r[1])),shown=limit?rows.slice(0,limit):rows,rest=rows.length-shown.length;return `<figure class="chart" id="${id}"><figcaption><h3>${E(title)}</h3><small>${E([note,unknown?t('data.unknownCount',{n:fmt(unknown)}):'',rest?t('data.more',{n:fmt(rest)}):''].filter(Boolean).join(' · '))}</small></figcaption>${shown.length?`<ol class="bars" aria-label="${E(title)}">${shown.map(([k,n])=>`<li><span class="bar-label">${E(label(k))}</span><span class="bar-track" aria-hidden="true"><span class="bar" style="width:${Math.max(1.5,n/max*100).toFixed(1)}%"></span></span><span class="bar-value">${fmt(n)}</span></li>`).join('')}</ol>`:`<p class="section-empty">${E(t('data.noValues'))}</p>`}</figure>`}
function exportFilters(){const out={};if(scope!=='all')out.scope=scope;for(const [k,v] of Object.entries(filters)){if(k==='sort'||v===''||v===false||v===null||v===undefined||Array.isArray(v)&&!v.length||(k==='category'||k==='district')&&v==='전체')continue;out[k]=v}return out}
function datasetCitation(n){return t('data.citeText',{n:fmt(n),date:C.today(),url:String(window.AOL_CONFIG?.PUBLIC_URL||'').replace(/\/+$/,'')+'/#data'})}
function exportCtx(ps){return {lang:uiLang(),recordURL,syncedAt:window.AOL_GLOBAL?.fetchedAt||'',filters:exportFilters(),version:APP_VERSION,citation:datasetCitation(ps.length)}}
function exportArchive(kind){const ps=results(),stem=(uiLang()==='en'?'architecture-of-light-archive_':'빛의건축_아카이브_')+C.today(),ctx=exportCtx(ps);if(kind==='csv')download(stem+'.csv',X.exportCSV(ps,ctx),'text/csv;charset=utf-8');else download(stem+'.json',JSON.stringify(X.exportJSON(ps,{...ctx,now:new Date().toISOString()}),null,2),'application/json');toast(t('data.exported',{n:fmt(ps.length)}))}
function dataPage(){if(indexPending())return `<header class="page-head"><h1 class="large-title">${E(t('data.title'))}</h1><p class="page-sub">${E(t('data.sub'))}</p></header>${loadingResults()}`;const ps=results(),st=X.stats(ps),onMap=ps.filter(X.mappable).length,photos=ps.filter(p=>mediaFor(p).length).length,countries=st.country.rows.length,lab=name=>k=>vlabel(name,k),L=uiLang();
 return `<header class="page-head"><h1 class="large-title">${E(t('data.title'))}</h1><p class="page-sub">${E(t('data.sub'))}</p></header><section class="data-scope"><p class="data-scope-line"><b>${E(whereLabel())}</b> · ${E(t('results.count',{n:fmt(ps.length)}))}</p>${activeChips()}<a class="text-link" href="#explore">${I('sliders-horizontal')}${E(t('data.changeFilters'))}${I('caret-right')}</a></section><div class="stat-strip data-stats">${[[ps.length,t('data.total')],[countries,t('data.countries')],[onMap,t('data.onMap')],[photos,t('data.withPhoto')]].map(([n,l])=>`<div class="stat"><b>${fmt(n)}</b><span>${E(l)}</span></div>`).join('')}</div>
 <section class="data-section" aria-labelledby="statsTitle"><div class="section-head"><div><h2 id="statsTitle">${E(t('data.stats'))}</h2><small>${E(t('data.statsSub'))}</small></div></div><div class="chart-grid">${barChart('chartRegion',t('facet.region'),st.region.rows,lab('region'),st.region)}${barChart('chartCountry',t('data.countryTop'),st.country.rows,countryName,{...st.country,limit:20})}${barChart('chartDecade',t('data.decade'),st.decade.rows,k=>t('data.decadeLabel',{v:k}),{...st.decade,note:t('data.yearNote')})}${barChart('chartType',t('facet.project_type'),st.project_type.rows,lab('project_type'),st.project_type)}${st.installation_method.rows.length?barChart('chartMethod',t('facet.installation_method'),st.installation_method.rows,lab('installation_method'),st.installation_method):''}${st.technology.rows.length?barChart('chartTech',t('facet.technology'),st.technology.rows,lab('technology'),{...st.technology,note:t('data.multiNote')}):''}</div>${st.year.rows.length?`<details class="year-details"><summary>${E(t('data.byYear'))}</summary>${barChart('chartYear',t('data.byYear'),st.year.rows,k=>String(k),st.year)}</details>`:''}</section>
 <section class="data-section" id="dataExport" aria-labelledby="exportTitle"><h2 id="exportTitle">${E(t('data.export'))}</h2><p class="section-note">${E(t('data.exportSub',{n:fmt(ps.length)}))}</p><p class="notice">${I('info')}<span>${E(X.WARNING[L])}</span></p><div class="actions export-actions"><button type="button" class="button" data-export="csv">${I('download-simple')}${E(t('data.csv'))}</button><button type="button" class="button tonal" data-export="json">${I('download-simple')}${E(t('data.json'))}</button></div><p class="section-note">${E(t('data.exportFormat'))}</p><details class="research-details dictionary"><summary>${E(t('data.dictionary'))}</summary><div class="table-scroll" tabindex="0" role="region" aria-label="${E(t('data.dictionary'))}"><table class="dict-table"><thead><tr><th scope="col">${E(t('data.field'))}</th><th scope="col">${E(t('data.type'))}</th><th scope="col">${E(t('data.description'))}</th></tr></thead><tbody>${X.EXPORT_FIELDS.map(([f,ty,ko,en])=>`<tr><td><code>${E(f)}</code></td><td>${E(ty)}</td><td>${E(L==='en'?en:ko)}</td></tr>`).join('')}</tbody></table></div></details><h3 class="licence-title" id="licenceTitle">${E(t('data.licTitle'))}</h3><dl class="kv-list licence-list" aria-labelledby="licenceTitle"><div class="kv"><dt>Wikidata</dt><dd>${E(t('data.licWikidata'))}</dd></div><div class="kv"><dt>Wikimedia Commons</dt><dd>${E(t('data.licCommons'))}</dd></div><div class="kv"><dt>${E(t('data.licEditorialLabel'))}</dt><dd>${E(t('data.licEditorial'))}</dd></div><div class="kv"><dt>${E(t('tab.sources'))}</dt><dd>${E(t('data.licSources'))}</dd></div></dl></section>
 <section class="data-section methodology" id="methodology" aria-labelledby="methodTitle"><h2 id="methodTitle">${E(t('data.method'))}</h2>${['sources','updates','images','classify','limits'].map(k=>`<h3>${E(t('m.'+k))}</h3><p>${E(t('m.'+k+'Text'))}</p>`).join('')}<h3>${E(t('m.cite'))}</h3><p>${E(t('m.citeText'))}</p><blockquote class="citation" id="datasetCitation">${E(datasetCitation(ps.length))}</blockquote><div class="cite-actions"><button type="button" class="button tonal" data-copy-dataset>${I('copy')}${E(t('cite.copy'))}</button></div></section>`}


// The map shows exactly the explore results that have usable coordinates (X.mappable); the list under it, its count
// and the clusters come from this one list (pinned in qa/archive.spec.mjs and qa/v17-scale.spec.mjs).
function mapProjects(){return results().filter(X.mappable)}


function mapItem(p){const m=photoFor(p);return `<button class="map-list-item" data-map-select="${E(p.place_id)}"><span class="map-item-art">${m?imgTag(m,'',{sizes:'56px',max:330}):placeholder(p,'ph-small')}</span><span class="map-item-text"><b>${E(nm(p))}</b><small>${E([category(p),placeLine(p)].filter(Boolean).join(' · '))}</small></span>${I('caret-right','map-item-caret')}</button>`}
// The list under the map: the same filtered places as the pins (all of them, or those in view once the map moved).
function mapResultHTML(bounds,all=mapProjects()){if(indexPending())return `<div class="result-meta" aria-busy="true"><b>${E(t('results.loading'))}</b></div>`;const ps=bounds?all.filter(p=>bounds.contains([p.latitude,p.longitude])):all,shown=ps.slice(0,showCount),off=results().length-all.length;return `<div class="result-meta" data-count="${ps.length}" data-total="${all.length}"><b>${E(bounds?t('map.here'):whereLabel())} · ${E(t('results.count',{n:fmt(ps.length)}))}</b>${off?`<span class="map-off">${E(t('map.offMap',{n:fmt(off)}))} <a class="text-link" href="#explore">${E(t('map.toList'))}</a></span>`:''}</div>${shown.map(mapItem).join('')||empty(t('map.emptyTitle'),t('map.emptyBody'))}${ps.length>shown.length?`<button class="button subtle more-button" data-more>${E(t('results.more',{n:fmt(Math.min(PAGE,ps.length-shown.length))}))}</button>`:''}`}

function updateMapList(all){const el=$('#mapResults');if(el)el.innerHTML=mapResultHTML(currentMap&&mapFitted?currentMap.getBounds():null,all)}
// Grid clustering (smooth with thousands of places): the places in view, plus a margin, fall into square cells of the
// screen at the current zoom; a cell with one place is a dot on the shared canvas renderer, with more a numbered disc
// that zooms in on it. Projected positions are cached per zoom level and list; popups are built when opened.
let mapProj=null,mapFitted=false;
function mapPopup(p){return `<div class="map-pop"><p class="map-pop-eyebrow">${E(category(p))}</p><a href="#place/${E(p.place_id)}"><b>${E(nm(p))}</b> ${E(t('pop.details'))}${I('caret-right','icon-sm')}</a>${placeLine(p)?`<small>${E(placeLine(p))}</small>`:''}</div>`}
function drawMap(){if(!currentMap||!mapLayer)return;const z=currentMap.getZoom(),b=currentMap.getBounds().pad(.3),size=(window.innerWidth||1024)<768?52:60,ps=mapShown,cells=new Map();if(!mapProj||mapProj.z!==z||mapProj.ps!==ps)mapProj={z,ps,pts:ps.map(p=>currentMap.project([p.latitude,p.longitude],z))};ps.forEach((p,i)=>{if(!b.contains([p.latitude,p.longitude]))return;const q=mapProj.pts[i],k=Math.floor(q.x/size)+':'+Math.floor(q.y/size);let c=cells.get(k);if(!c)cells.set(k,c={ps:[],x:0,y:0});c.ps.push(p);c.x+=q.x;c.y+=q.y});mapLayer.clearLayers();mapMarkers=[];let sum=0,groups=0;
 for(const c of cells.values()){const n=c.ps.length;sum+=n;let m;if(n===1){const p=c.ps[0];m=L.circleMarker([p.latitude,p.longitude],{renderer:mapRenderer,radius:7,weight:2,color:'#FFFFFF',fillColor:'#6B52DE',fillOpacity:1});m.aolId=p.place_id;m.on('click',()=>{if(!m.getPopup())m.bindPopup(mapPopup(p));m.openPopup()})}else{groups++;const ll=currentMap.unproject([c.x/n,c.y/n],z),d=n<10?34:n<100?42:n<1000?50:58;m=L.marker(ll,{icon:L.divIcon({className:'map-cluster',html:`<span>${fmt(n)}</span>`,iconSize:[d,d]}),title:t('map.cluster',{n:fmt(n)}),alt:t('map.cluster',{n:fmt(n)}),keyboard:true});m.aolCount=n;m.aolIds=c.ps.map(p=>p.place_id);m.on('click',()=>{const bb=L.latLngBounds(c.ps.map(p=>[p.latitude,p.longitude]));if(bb.getNorthEast().equals(bb.getSouthWest())||z>=18)currentMap.setView(bb.getCenter(),Math.min(19,z+2));else currentMap.fitBounds(bb.pad(.2))})}mapLayer.addLayer(m);mapMarkers.push(m)}
 const el=$('#mapCanvas');if(el){el.dataset.points=String(sum);el.dataset.clusters=String(groups);el.dataset.total=String(ps.length)}}
// Places on the map: the explore results with usable coordinates (X.mappable). Typing is debounced; a background update
// that leaves the list as it was keeps the markers.
function updateMapResults(){clearTimeout(mapTimer);mapTimer=null;if(!$('#mapResults'))return;const ps=mapProjects();updateMapList(ps);refreshFilters();if(!currentMap||!mapLayer)return;if(ps.length===mapShown.length&&ps.every((p,i)=>p===mapShown[i]))return;mapShown=ps;drawMap()}
function fitMap(){if(!currentMap)return;const ps=mapShown;if(ps.length){let s=90,w=180,n=-90,e=-180;for(const p of ps){if(p.latitude<s)s=p.latitude;if(p.latitude>n)n=p.latitude;if(p.longitude<w)w=p.longitude;if(p.longitude>e)e=p.longitude}currentMap.fitBounds([[s,w],[n,e]],{padding:[24,24],maxZoom:15,animate:false})}else currentMap.setView([25,10],2,{animate:false});mapFitted=true}

async function privatePhotos(visitId){if(!window.AOLCloud?.state.user){toast(t('private.signIn'));return}const uid=window.AOLCloud.state.user.id,el=modal(t('private.title'),`<p class="muted">${E(t('private.body'))}</p><input id="privatePhotoInput" type="file" accept="image/jpeg,image/png,image/webp" aria-label="${E(t('private.pick'))}"><div id="privatePhotoStatus" role="status"></div><div id="privatePhotoList"></div>`);const status=$('#privatePhotoStatus'),list=$('#privatePhotoList');const show=async()=>{const rows=await window.AOLCloud.photos.list(visitId);if(!el.open||window.AOLCloud.state.user?.id!==uid)return;list.innerHTML=rows.map(p=>`<figure><img class="photo" src="${E(C.safeURL(p.url))}" alt="${E(t('private.alt'))}"><button class="button danger small" data-private-delete="${E(p.id)}">${E(t('private.delete'))}</button></figure>`).join('')||`<p>${E(t('private.none'))}</p>`;list.querySelectorAll('[data-private-delete]').forEach(b=>b.onclick=async()=>{if(!confirm(t('private.confirm')))return;try{await window.AOLCloud.photos.remove(b.dataset.privateDelete);await show()}catch(e){status.textContent=e.message}})};$('#privatePhotoInput').onchange=async e=>{const file=e.target.files[0];if(!file)return;status.textContent=t('private.saving');try{await window.AOLCloud.photos.upload(visitId,file);await show();status.textContent=t('private.saved')}catch(e){status.textContent=e.message}e.target.value=''};try{await show()}catch(e){status.textContent=e.message}}

// One of four brand gradients per place, so a grid of places without photos does not repeat one box.
function tone(id){let h=0;for(const ch of String(id||''))h=(h*31+ch.charCodeAt(0))>>>0;return h%4}
function railNav(){return `<span class="rail-nav" hidden><button type="button" class="rail-btn" data-rail-step="-1" aria-label="${E(t('rail.prev'))}" disabled>${I('caret-left')}</button><button type="button" class="rail-btn" data-rail-step="1" aria-label="${E(t('rail.next'))}">${I('caret-right')}</button></span>`}
// Desktop rails are one row (3 or 4 cards) that scrolls sideways; the arrows show only when there is more to see.
function railState(){for(const r of document.querySelectorAll?.('.rail-scroll')||[]){const nav=r.closest('section')?.querySelector('.rail-nav');if(!nav)continue;const update=()=>{const max=r.scrollWidth-r.clientWidth;nav.hidden=max<8;const [prev,next]=nav.querySelectorAll('button');if(prev)prev.disabled=r.scrollLeft<8;if(next)next.disabled=r.scrollLeft>max-8};r.onscroll=update;update()}}
function spyTabs(){const tabs=[...document.querySelectorAll?.('.section-tabs button')||[]].filter(b=>b.offsetParent!==null);if(!tabs.length)return;const line=(document.querySelector('.section-tabs')?.getBoundingClientRect().bottom||0)+24;let cur=tabs[0];for(const b of tabs){const el=document.getElementById(b.dataset.scrollTo);if(el&&el.getBoundingClientRect().top<=line)cur=b}if((window.innerHeight+window.scrollY)>=document.documentElement.scrollHeight-4)cur=tabs[tabs.length-1];for(const b of tabs){b.classList.toggle('active',b===cur);if(b===cur)b.setAttribute('aria-current','true');else b.removeAttribute('aria-current')}}